package fixture.spring;

import fixture.spring.events.Started;
import org.springframework.context.ApplicationListener;
import org.springframework.stereotype.Component;

@Component
public final class InterfaceListener implements ApplicationListener<Started> {
    @Override
    public void onApplicationEvent(Started event) { Sink.record("typed interface listener"); }
}

package fixture.spring;

import fixture.spring.events.Created;
import org.springframework.context.ApplicationEvent;
import org.springframework.context.PayloadApplicationEvent;
import org.springframework.context.event.EventListener;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionPhase;
import org.springframework.transaction.event.TransactionalEventListener;

@Component
public final class Listeners {
    @EventListener
    public void onPayload(Created event) { Sink.record("payload"); }

    @EventListener(classes = Created.class)
    public void onExplicitPayload() { Sink.record("explicit payload"); }

    @EventListener(condition = "#root.args[0].id == 'enabled'")
    public void onConditionalPayload(Created event) { Sink.record("conditional payload"); }

    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    public void onCommittedPayload(Created event) { Sink.record("committed payload"); }

    @Async
    @EventListener
    public void onAsyncPayload(Created event) { Sink.record("async payload"); }

    @EventListener
    public void onPayloadEnvelope(PayloadApplicationEvent<Created> event) { Sink.record("payload envelope"); }

    @EventListener
    public void onAnyApplicationEvent(ApplicationEvent event) { Sink.record("application event"); }

    @EventListener
    public void onOtherCreated(fixture.spring.other.Created event) { Sink.record("different qualified payload"); }

    @fixture.spring.fake.EventListener
    public void onPretendAnnotation(Created event) { Sink.record("pretend annotation"); }

    public void ordinaryMethod(Created event) { Sink.record("not a listener"); }
}

package fixture.spring.http;

import fixture.spring.Sink;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api")
public final class HttpController {
    @GetMapping("/items")
    public String items() { Sink.record("http items"); return "items"; }

    @GetMapping("/items/{id}")
    public String item() { Sink.record("http item"); return "item"; }

    @PostMapping("/items")
    public void create() { Sink.record("http create"); }

    @RequestMapping(path = "/health", method = RequestMethod.GET)
    public String health() { Sink.record("http health"); return "ok"; }

    @fixture.spring.fake.GetMapping("/pretend")
    public void pretend() { Sink.record("custom annotation is not Spring"); }
}

package fixture.spring.http;

import fixture.spring.Sink;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api")
public final class ConstrainedController {
    @GetMapping(path = "/ambiguous", produces = "application/json")
    public String json() { Sink.record("json variant"); return "{}"; }

    @GetMapping(path = "/ambiguous", produces = "text/plain")
    public String text() { Sink.record("text variant"); return "text"; }

    @GetMapping("/constrained")
    public String unconstrained() { Sink.record("unconstrained variant"); return "default"; }

    @GetMapping(path = "/constrained", params = "mode=special")
    public String constrained() { Sink.record("query constrained variant"); return "special"; }
}

